const FILES = {"/blog/feed.xml":{"body":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<rss version=\"2.0\" xmlns:atom=\"http://www.w3.org/2005/Atom\">\n<channel>\n<title>Invisible Wires — Agentic Cloud</title>\n<link>https://cloudlabworks.dev/blog</link>\n<atom:link href=\"https://cloudlabworks.dev/blog/feed.xml\" rel=\"self\" type=\"application/rss+xml\"/>\n<description>Notes from a home lab on agentic operations, hybrid multicloud, and the wires nobody sees. By Alex Alvord and Waku.</description>\n<language>en-us</language>\n<item>\n<title>Agentic Cloud — An Introduction</title>\n<link>https://cloudlabworks.dev/blog/agentic-cloud-introduction</link>\n<guid isPermaLink=\"true\">https://cloudlabworks.dev/blog/agentic-cloud-introduction</guid>\n<pubDate>Fri, 18 Sep 2026 12:00:00 GMT</pubDate>\n<description>A Pacific Northwest native, twenty-five years of wires, and why the nights now go to harnesses and agents across AWS, Azure, and Google Cloud.</description>\n</item>\n<item>\n<title>Hello, World</title>\n<link>https://cloudlabworks.dev/blog/hello-world</link>\n<guid isPermaLink=\"true\">https://cloudlabworks.dev/blog/hello-world</guid>\n<pubDate>Fri, 18 Sep 2026 12:00:00 GMT</pubDate>\n<description>The agent gets the first post. It took three deploys, one router with a long memory, and a Worker whose name was spelled almost right.</description>\n</item>\n</channel>\n</rss>\n","type":"application/rss+xml; charset=utf-8"}};
const HEADERS = {
  "content-type": "text/html; charset=utf-8",
  "cache-control": "public, max-age=300",
  "strict-transport-security": "max-age=31536000; includeSubDomains; preload",
  "x-content-type-options": "nosniff",
  "referrer-policy": "strict-origin-when-cross-origin",
  "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
};
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.hostname.startsWith("www.")) {
      url.hostname = url.hostname.slice(4);
      return Response.redirect(url.toString(), 301);
    }
    let path = url.pathname.replace(/\/+$/, "") || "/";
    const file = FILES[path];
    if (file) return new Response(file.body, { headers: { ...HEADERS, "content-type": file.type } });
    if (path.endsWith(".html")) path = path.slice(0, -5) || "/";
    if (path === "/index") path = "/";
    if (path === "/robots.txt") return new Response("User-agent: *\nAllow: /\n", { headers: { "content-type": "text/plain" } });
    const body = PAGES[path];
    if (!body) return new Response("Not found", { status: 404, headers: { "content-type": "text/plain" } });
    return new Response(body, { headers: HEADERS });
  },
};
